import json

lines = open('ios_crash.ips').readlines()
metadata = json.loads(lines[0])
crash = json.loads(''.join(lines[1:]))

# .NET image indices
dotnet_images = {}
for i, img in enumerate(crash['usedImages']):
    name = img.get('name', '')
    if any(x in name for x in ['libcoreclr', 'libmonosgen', 'libSystem.', 'libmscordac', 'libmscordbi', 'SampleMAUI']):
        if 'uuid' in img:
            dotnet_images[i] = img

print('=== .NET Runtime Images ===')
for idx, img in sorted(dotnet_images.items()):
    base_hex = hex(img['base'])
    print(f'  [{idx}] {img[\"name\"]:45s} base={base_hex}  uuid={img[\"uuid\"]}  arch={img.get(\"arch\",\"?\")}')

# Find unsymbolicated frames in faulting thread and lastExceptionBacktrace
faulting_idx = crash['faultingThread']
faulting_thread = crash['threads'][faulting_idx]

print(f'\n=== Faulting Thread (thread {faulting_idx}) - Unsymbolicated .NET frames ===')
for i, frame in enumerate(faulting_thread['frames']):
    img_idx = frame['imageIndex']
    if img_idx in dotnet_images and 'symbol' not in frame:
        img = dotnet_images[img_idx]
        addr = img['base'] + frame['imageOffset']
        print(f'  Frame #{i}: imageIndex={img_idx} ({img[\"name\"]}) addr={hex(addr)} offset={hex(frame[\"imageOffset\"])}')

print(f'\n=== All Threads - Unsymbolicated .NET frames ===')
for t_idx, thread in enumerate(crash['threads']):
    for i, frame in enumerate(thread['frames']):
        img_idx = frame['imageIndex']
        if img_idx in dotnet_images and 'symbol' not in frame:
            img = dotnet_images[img_idx]
            addr = img['base'] + frame['imageOffset']
            print(f'  Thread {t_idx} Frame #{i}: imageIndex={img_idx} ({img[\"name\"]}) addr={hex(addr)} offset={hex(frame[\"imageOffset\"])}')

print(f'\n=== lastExceptionBacktrace - Unsymbolicated .NET frames ===')
if 'lastExceptionBacktrace' in crash:
    for i, frame in enumerate(crash['lastExceptionBacktrace']):
        img_idx = frame['imageIndex']
        if img_idx in dotnet_images and 'symbol' not in frame:
            img = dotnet_images[img_idx]
            addr = img['base'] + frame['imageOffset']
            print(f'  Frame #{i}: imageIndex={img_idx} ({img[\"name\"]}) addr={hex(addr)} offset={hex(frame[\"imageOffset\"])}')
